{{begin-eqn}}
{{eqn | l = \frac 1 n \sum_{i \mathop = 1}^n \ln x_i
| r = \frac 1 n \map \ln {\prod_{i \mathop = 1}^n x_i}
| c = [[Sum of Logarithms]]
}}
{{eqn | r = \map \ln {\paren {\prod_{i \mathop = 1}^n x_i}^{1 / n} }
